'use client';

import { useAuthStore } from '@/stores/auth.store';
import { useBranchSelector } from '@/hooks/use-branch-selector';
import { useTranslation } from '@/i18n';
import { BranchSelector } from '@/components/dashboard/branch-selector';
import { SummaryCards } from '@/components/dashboard/summary-cards';
import { AttendanceChart } from '@/components/dashboard/attendance-chart';
import { AlertsExceptions } from '@/components/dashboard/alerts-exceptions';
import { RecentActivity } from '@/components/dashboard/recent-activity';
import { AISmartInsights } from '@/components/dashboard/ai-smart-insights';
import { TopPerformers } from '@/components/dashboard/top-performers';
import { MotionStagger, MotionCard } from '@/components/dashboard/motion-wrapper';
import { SetupCTACard } from '@/components/dashboard/setup-cta-card';
import { Building2, CalendarDays } from 'lucide-react';

export default function DashboardPage() {
  const { userData } = useAuthStore();
  const { branches, selectedSid, setSelectedSid, loadingBranches } =
    useBranchSelector();
  const { t: tDashboard } = useTranslation('dashboard');
  const { t: tGreeting } = useTranslation('greeting');
  const { locale } = useTranslation('common');

  const getGreeting = () => {
    const hour = new Date().getHours();
    if (hour < 12) return tGreeting('morning');
    if (hour < 17) return tGreeting('afternoon');
    return tGreeting('evening');
  };

  const getGreetingEmoji = () => {
    const hour = new Date().getHours();
    if (hour < 12) return '🌅';
    if (hour < 17) return '☀️';
    return '🌙';
  };

  const todayFormatted = new Date().toLocaleDateString(
    locale === 'ms' ? 'ms-MY' : 'en-GB',
    { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }
  );

  return (
    <MotionStagger className="space-y-6">
      {/* Setup CTA — shown when setup is incomplete */}
      <MotionCard>
        <SetupCTACard selectedSid={selectedSid} />
      </MotionCard>

      {/* Greeting */}
      <MotionCard>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="animate-text-reveal text-xl font-bold tracking-tight flex items-center gap-2">
              {getGreeting()}, {userData?.user_name || 'Admin'}
              <span className="text-lg">{getGreetingEmoji()}</span>
            </h1>
            <p className="animate-text-reveal-delayed text-sm text-muted-foreground">{tDashboard('subtitle')}</p>
          </div>
          <div className="hidden sm:flex items-center gap-1.5 text-xs text-muted-foreground">
            <CalendarDays className="h-3.5 w-3.5" />
            <span>{todayFormatted}</span>
          </div>
        </div>
      </MotionCard>

      {/* Branch selector — prominent, own row */}
      <MotionCard>
        <div className="inline-flex items-center gap-2.5 rounded-xl border bg-card px-3.5 py-2 shadow-sm">
          <Building2 className="h-4 w-4 text-primary shrink-0" />
          <span className="text-xs font-medium text-muted-foreground">{tDashboard('branch')}</span>
          <BranchSelector
            branches={branches}
            selectedSid={selectedSid}
            onBranchChange={setSelectedSid}
            loading={loadingBranches}
          />
        </div>
      </MotionCard>

      {/* Row 2: Summary Cards */}
      <MotionCard>
        <SummaryCards selectedSid={selectedSid} />
      </MotionCard>

      {/* Row 3: Attendance Trend + Alerts */}
      <MotionCard>
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <AttendanceChart selectedSid={selectedSid} />
          <AlertsExceptions selectedSid={selectedSid} />
        </div>
      </MotionCard>

      {/* Row 4: Smart Insights + Top Performers */}
      <MotionCard>
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          <AISmartInsights selectedSid={selectedSid} />
          <TopPerformers selectedSid={selectedSid} />
        </div>
      </MotionCard>

      {/* Row 5: Recent Activity */}
      <MotionCard>
        <RecentActivity selectedSid={selectedSid} />
      </MotionCard>
    </MotionStagger>
  );
}
